INSERT INTO affiliate_picks (title, creator, blurb, query, asin, match_keywords, topics, sort) VALUES ('Night Siege', 'J. Allen Hynek, Philip Imbrogno & Bob Pratt', '7,000+ sightings of silent boomerang craft over New York and Connecticut, 1982–86 — investigated by Hynek himself. The mass-sighting classic for the triangle files.', 'Night Siege Hudson Valley UFO Hynek Imbrogno', 'B0036DD2LC', 'hudson valley,triangle,boomerang,imbrogno', '', 24);
INSERT INTO affiliate_picks (title, creator, blurb, query, asin, match_keywords, topics, sort) VALUES ('The Interrupted Journey', 'John G. Fuller', 'September 1961, New Hampshire: the first abduction book, built from the Hills'' hypnosis transcripts — and they filed a contemporaneous Air Force report. Where the modern abduction story starts.', 'The Interrupted Journey John Fuller Betty Barney Hill', '0285624504', 'hill,betty,barney,abduction', '', 25);
INSERT INTO affiliate_picks (title, creator, blurb, query, asin, match_keywords, topics, sort) VALUES ('Fire in the Sky', 'Travis Walton', 'November 1975, Arizona: six loggers watch Walton taken, polygraphs all round, five days gone. The abduction case with the most witnesses — and a Hollywood film.', 'Fire in the Sky Travis Walton', '1569247102', 'walton,heber,snowflake,apache-sitgreaves', '', 26);
INSERT INTO affiliate_picks (title, creator, blurb, query, asin, match_keywords, topics, sort) VALUES ('Mirage Men', 'Mark Pilkington', 'The uncomfortable one: a journalist argues US intel promoted crashed-saucer stories — Bennewitz, Dulce, AFOSI''s Richard Doty — as cover for classified programs. Read it alongside the cover-up histories.', 'Mirage Men Mark Pilkington', '1845298578', 'disinformation,bennewitz,dulce,doty', '', 27);
INSERT INTO affiliate_picks (title, creator, blurb, query, asin, match_keywords, topics, sort) VALUES ('Area 51', 'Annie Jacobsen', 'The declassified history of Groom Lake — U-2, OXCART, Have Blue — plus the book''s notorious claim that Roswell was a Soviet hoax. Essential context, controversial ending.', 'Area 51 Annie Jacobsen', '0316202304', 'area 51,groom lake,roswell', '', 28);
